export const LEVELS_BY_LANGUAGE = {
  'zh-CN': LEVELS.filter((l) => l.language === 'zh-CN'),
  'en-US': LEVELS.filter((l) => l.language === 'en-US'),
}

export function getLevel(id) {
  return LEVELS.find((level) => level.id === id) || null
}
